import pandas as pd

def top_three_salaries(employee: pd.DataFrame, department: pd.DataFrame) -> pd.DataFrame:
    if employee.empty or department.empty:
        return pd.DataFrame(columns=['Department', 'Employee', 'Salary'])
    merged = employee.merge(department, left_on='departmentId', right_on='id', suffixes=('', '_dept'))
    merged['rnk'] = merged.groupby('departmentId')['salary'].rank(method='dense', ascending=False)
    top3 = merged[merged['rnk'] <= 3]
    return top3[['name_dept', 'name', 'salary']].rename(columns={'name_dept': 'Department', 'name': 'Employee', 'salary': 'Salary'})
